private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb){
    while (i < bb.limit()) {
        int b = bb.get(i);
        if ((b & 0xC0) == 0xC0) { // B1100 0000
            // Multibyte sequence starts
            if ((b & 0x30) == 0x20) { // B110 0000 001 0000
                // B110 0000 001 0000 1000 0000 (4 bytes)
                sb.append((char) (b & 0x03FF));
                i += 2
            } else if ((b & 0x34) == 0x34) { // B110 0000 001 0010
                // B110 0000 001 0010 0111 1000 0000 (5 bytes)
                sb.append((char) (b & 0x03FF));
                i += 3
            } else if ((b & 0x38) == 0x38) { // B110 0000 001 0100
                // B110 0000 001 0100 1111 1111 1000 0000 (6 bytes)
                sb.append((char) (b & 0x03FF));
                i += 4
            } else if ((b & 0x3C) == 0x3C) { // B110 0000 001 0110
                // B110 0000 001 0110 1111 1111 1111 1000 0000 (7 bytes)
                sb.append((char) (b & 0x03FF));
                i += 5
            } else if ((b & 0x3E) == 0x3E) { // B110 0000 001 1000
                // B110 0000 001 1000 1111 1111 1111 1000 0000 (8 bytes)
                sb.append((char) (b & 0x03FF));
                i += 6
            }
        } else {
            // Single byte character
            sb.append((char) b);
            i++;
        }
    }
    return i;
}
