private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    int shifts = 0;
    while (!bb.isZero(7)) {
        shifts += 7;
        byte value = bb.get();
        int charValue = value & 0xFF;
        sb.append((char) (charValue >> shifts));
    }
    shifts += 7;
    byte lastByte = bb.get();
    int charValue = lastByte & 0xFF;
    sb.append((char) (charValue >> shifts));
    return i + bb.position();
}
