     * Skips bytes until the end of the current line.
     * @param headerPart The headers, which are being parsed.
     * @param end_index The index of the last byte, which has yet been processed.
     * @return The index of the \r\n sequence, which indicates end of line.
     */
    private int parseEndOfLine(String headerPart, int end_index) {
        for (int i = end_index; i >= 0; i--) {
            if (headerPart.charAt(i) == '\n') {
                return i;
            }
            if (headerPart.charAt(i) == '\r') {
                return i - 1;
            }
        }
        return -1;
    }
}
