import java.util.function.Function;

public class GraphUtil {
    /**
     * Computes an identity automorphism (i.e. a self-mapping of a graph in which each vertex also maps to itself).
     * @param graph the input graph
     * @param < V > the graph vertex type
     * @param < E > the graph edge type
     * @return a mapping from graph to graph
     */
    public static <V,E> Function<Graph<V,E>,Graph<V,E>> identity(Graph<V,E> graph) {
        return vertex -> new IsomorphicGraphMapper<>(graph, vertex);
    }
}

class IsomorphicGraphMapper<V,E> implements Function<Graph<V,E>,Graph<V,E>> {
    private final Graph<V,E> originalGraph;
    private final V mappedVertex;

    public IsomorphicGraphMapper(Graph<V,E> originalGraph, V mappedVertex) {
        this.originalGraph = originalGraph;
        this.mappedVertex = mappedVertex;
    }

    @Override
    public Graph<V,E> apply(Graph<V,E> graph) {
        return originalGraph;
    }
}
