private static Class<?> resolveType(Type type, Class<?> targetType){
    if (type instanceof WildcardType) {
        WildcardType wildcardType = (WildcardType) type;
        if (wildcardType.getUpperBounds().length == 0) {
            throw new IllegalArgumentException("Upper bound cannot be null for wildcard type");
        }
        return resolveType(wildcardType.getUpperBounds()[0], targetType);
    } else if (type instanceof Class<?>) {
        return (Class<?>) type;
    } else if (type instanceof TypeVariable<?>) {
        TypeVariable<?> typeVariable = (TypeVariable<?>) type;
        return resolveType(typeVariable.getBounds()[0], targetType);
    } else {
        throw new IllegalArgumentException("Unsupported type: " + type);
    }
}
