public class TimeRangeBuilder {

    @SuppressWarnings("unused")
    protected List<TimeRange> buildTimeRanges(long start, long end) {
        // Constants for fetching data durations
        final long FETCH_DATA_DURATION = 60 * 60 * 24; // 24 hours in minutes

        List<TimeRange> timeRanges = new ArrayList<>();

        // Ensure the start and end time are less than the FETCH_DATA_DURATION
        if (end - start <= FETCH_DATA_DURATION) {
            timeRanges.add(new TimeRange(start, end));
        } else {
            // Split the time ranges into smaller time intervals
            long interval = FETCH_DATA_DURATION / 5; // 5 minutes interval
            long current = start;
            while (current < end) {
                long next = Math.min(current + interval, end);
                timeRanges.add(new TimeRange(current, next));
                current += interval;
            }
        }

        return timeRanges;
    }

    // A simple TimeRange class to represent a time interval
    private static class TimeRange {
        private long start;
        private long end;

        public TimeRange(long start, long end) {
            this.start = start;
            this.end = end;
        }

        @Override
        public String toString() {
            return "TimeRange{" +
                    "start=" + start +
                    ", end=" + end +
                    '}';
        }
    }
}
