public List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();

    // Calculate the difference between end and start
    long duration = Math.abs(end - start);

    // Calculate the maximum allowed range length
    long maxRange = FETCH_DATA_DURATION;

    // Determine how many time ranges are needed based on the difference
    int numRanges = (int) Math.ceil((double) duration / maxRange);

    // Calculate the range lengths for each time range
    for (int i = 0; i < numRanges; i++) {
        long startRange = start + i * maxRange;
        long endRange = Math.min(startRange + maxRange, end);
        timeRanges.add(new TimeRange(startRange, endRange));
    }

    return timeRanges;
}
