public static int computeUTF8Size(CharSequence str, int index, int len) {
    int size = 0;
    while (len-- > 0) {
        char c = str.charAt(index);
        index++;
        if (c < 128) { // ASCII
            size++;
        } else if (c < 192) { // Latin-1 Supplement
            size += 1;
        } else if (c < 224) { // Latin-2 Supplement
            size += 2;
        } else if (c < 240) { // Latin-3 Supplement
            size += 3;
        } else if (c < 248) { // Latin-4 Supplement
            size += 4;
        } else if (c < 252) { // Latin-5 Supplement
            size += 5;
        } else if (c < 254) { // Latin-6 Supplement
            size += 6;
        } else { // Multibyte Encodings
            int count = 0;
            int b3 = str.charAt(index);
            while (b3 >= 224) {
                int b4 = str.charAt(index + 1);
                count += 4;
                index += 2;
            }
            size += count;
        }
    }
    return size;
}
