    for (int i = index; i < index + len; i++) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size++;
        } else if (ch < 0xC0) {
            return -1; // Invalid byte for single-byte character
        } else if (ch < 0xE0) {
            size += 2;
        } else if (ch < 0xF0) {
            size += 3;
        } else if (ch < 0xF8) {
            size += 4;
        } else if (ch < 0xFC) {
            size += 5;
        } else if (ch < 0xFE) {
            size += 6;
        } else {
            return -1; // Invalid byte for multi-byte character
        }
    }
    return size;
}
