public static void writeUTF8(final CharSequence str, final WriteSession session, final LinkedBuffer lb) {
    for (int i = 0; i < str.length(); i++) {
        int c = str.charAt(i);
        if (c < 0x80) {
            lb.put((byte) c);
        } else if (c < 0xC0) {
            lb.put(0xC0 | (c >> 6));
            lb.put(0x80 | (c & 0x3F));
        } else if (c < 0xe0) {
            lb.put(0xE0 | (c >> 5));
            lb.put(0x80 | ((c >> 2) & 0x3F));
            lb.put(0x80 | (c & 0x3F));
        } else {
            lb.put(0xF0 | (c >> 4));
            lb.put(0x80 | ((c >> 1) & 0x3F));
            lb.put(0x80 | ((c >> 0) & 0x3F));
            lb.put(0x80 | (c & 0x3F));
        }
    }
}
