    for (int i = 0; i < len; i++) {
        int c = (int) str.charAt(i);
        if (c >= 0 && c <= 127) {
            lb.writeStringByte((byte) c);
        } else if (c >= 128 && c <= 2047) {
            lb.writeStringByte((byte) ((c >> 6) | 192));
            lb.writeStringByte((byte) ((c & 63) | 128));
        } else if (c >= 2048 && c <= 65535) {
            lb.writeStringByte((byte) ((c >> 12) | 224));
            lb.writeStringByte((byte) ((c >> 6) & 63));
            lb.writeStringByte((byte) ((c & 63) | 128));
        }
    }
    return lb;
}
