public class VarintInputStream {
    private InputStream inputStream;

    public VarintInputStream(InputStream inputStream) {
        this.inputStream = inputStream;
    }

    public long readRawVarint64() throws IOException {
        byte[] buffer = new byte[8];
        int bytesRead = inputStream.read(buffer);
        if (bytesRead == -1) {
            throw new IOException("End of stream reached");
        }

        long value = 0;
        for (int i = 0; i < bytesRead; i++) {
            value <<= 8;
            value |= buffer[i] & 0xFF;
        }

        // Check for the high bit to determine if the stream ends with a long value
        if ((buffer[bytesRead - 1] & 0x80) != 0) {
            long highBits = 0;
            for (int i = bytesRead - 1; i > 7; i--) {
                highBits <<= 8;
                highBits |= buffer[i] & 0xFF;
            }
            value |= highBits << (bytesRead - 8);
        }

        return value;
    }
}
