public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    // Calculate the midpoint along the x-axis
    double xMidpoint = box.getMinX() + (box.getMaxX() - box.getMinX()) / 2;

    // Create two equal boxes, one for the left half and one for the right half
    Box2D leftHalf = new Box2D(box.getMinX(), xMidpoint, box.getMaxY(), box.getMaxZ());
    Box2D rightHalf = new Box2D(xMidpoint, box.getMaxX(), box.getMaxY(), box.getMaxZ());

    // Return a Pair containing the two resulting boxes
    return new Pair<>(leftHalf, rightHalf);
}
