public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 3) {
        return 3;
    }

    int limit = desiredCapacity + (desiredCapacity >> 1) + (desiredCapacity >> 2);
    for (int i = (desiredCapacity >> 1) + 1; i <= limit; i++) {
        if (isPrime(i)) {
            return i;
        }
    }

    throw new IllegalArgumentException("No prime number found for desired capacity");
}

private static boolean isPrime(int n) {
    if (n <= 1) {
        return false;
    }

    for (int i = 2; i <= Math.sqrt(n); i++) {
        if (n % i == 0) {
            return false;
        }
    }

    return true;
}
