public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 2) {
        return 2;
    }
    int left = desiredCapacity == 0 ? 1 : desiredCapacity + 2;
    int right = desiredCapacity == 0 ? 3 : desiredCapacity * 2 + 3;
    while (right - left > 2) {
        int center = left + (right - left) / 2;
        if (isPrime(center)) {
            left = center;
        } else {
            right = center;
        }
    }
    return left;
}

private static boolean isPrime(int number) {
    if (number <= 1) {
        return false;
    }
    if (number <= 3) {
        return true;
    }
    if (number % 2 == 0 || number % 3 == 0) {
        return false;
    }
    int i = 5;
    while (i * i <= number) {
        if (number % i == 0 || number % (i + 2) == 0) {
            return false;
        }
        i += 6;
    }
    return true;
}
