private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> contentMap = new HashMap<>();
    for (Map.Entry<String, JsonElement> entry : jsonObject.entrySet()) {
        contentMap.put(entry.getKey(), convertToJsonValue(entry.getValue()));
    }
    return contentMap;
}

private Object convertToJsonValue(JsonElement element) {
    if (element.isJsonPrimitive()) {
        return element.getAsJsonPrimitive().getAsNumber() == Double.MIN_VALUE ? null : element.getAsJsonPrimitive().toString();
    } else if (element.isJsonObject()) {
        JsonObject subObject = element.getAsJsonObject();
        return subObject.entrySet().stream()
                .collect(Collectors.toMap(entry -> entry.getKey(), entry -> convertToJsonValue(entry.getValue())));
    } else if (element.isJsonArray()) {
        JsonArray subArray = element.getAsJsonArray();
        return subArray.stream()
                .map(subElement -> convertToJsonValue(subElement))
                .collect(Collectors.toList());
    }
    return null;
}
