public static String unescapeJava(String str) {
    if (str == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    int len = str.length();
    boolean escaping = false;
    for (int i = 0; i < len; i++) {
        char c = str.charAt(i);
        if (escaping) {
            switchingEscapingMode(c, i, result);
        } else {
            if (c == '\\') {
                escaping = true;
            } else {
                result.append(c);
            }
        }
    }
    return result.toString();
}

private static void switchingEscapingMode(char c, int i, StringBuilder result) throws Exception {
    switch (c) {
        case '\\':
            if (i + 1 < result.length() && result.charAt(i + 1) == '\\') {
                result.append(c); // double the escape character
                i++;
            } else {
                result.append('\n'); // treat as newline
            }
            break;
        case '\'':
            if (i + 1 < result.length() && result.charAt(i + 1) == '\\') {
                result.append(c); // double the escape character
                i++;
            } else {
                result.append(c); // treat as quote
            }
            break;
        case '"':
            if (i + 1 < result.length() && result.charAt(i + 1) == '\\') {
                result.append(c); // double the escape character
                i++;
            } else {
                result.append(c); // treat as double quote
            }
            break;
        case '/':
            if (i + 1 < result.length() && result.charAt(i + 1) == '\\') {
                result.append(c); // double the escape character
                i++;
            } else {
                result.append('/'); // treat as division
            }
            break;
        default:
            result.append(c); // append any other character
            break;
    }
}
