private static Object copyArrayGrow1(final Object array,final Class<?> newArrayComponentType) {
    if (array == null) {
        int length = newArrayComponentType.isArray() ? Array.getLength(newArrayComponentType) : 0;
        return Array.newInstance(newArrayComponentType, length + 1);
    } else if (newArrayComponentType == null) {
        if (array instanceof Object[]) {
            return copyArrayGrow1((Object[]) array, array.getClass()[0]);
        }
    }
    // Assuming array is a primitive array
    int length = array.length;
    Object newArray = Array.newInstance(array.getClass().getComponentType(), length + 1);
    System.arraycopy(array, 0, newArray, 0, length);
    return newArray;
}
