public ByteVector putByteArray(byte[] byteArrayValue, int byteOffset, int byteLength) {
    if (byteArrayValue == null && byteLength == 0) {
        return this; // If byteArrayValue is null and byteLength is 0, do nothing
    }

    // If byteLength is greater than the remaining length of the array, extend the array
    byte[] extendedArray = new byte[Math.max(this.bytes.length + byteLength, byteOffset + byteLength)];
    System.arraycopy(this.bytes, 0, extendedArray, 0, Math.min(this.bytes.length, byteOffset));
    System.arraycopy(byteArrayValue, byteOffset, extendedArray, Math.min(this.bytes.length, byteOffset) + this.bytes.length - byteOffset, byteLength);
    this.bytes = extendedArray;

    return this;
}
