void addReverse(InputStream[] files) {
    if (files == null || files.length == 0) {
        return;
    }
    int totalFiles = files.length;
    for (int i = 0; i < totalFiles; i++) {
        try {
            // Implement the actual addition of the file in reverse order
            // This may involve saving the content in reverse order or storing in a secondary location
            // Example: write content in reverse order to another file
            appendToReverseOrder(files[i], " reversedFiles_" + i + ".bin");
        } catch (IOException e) {
            e.printStackTrace();
        }
    }
}

private void appendToReverseOrder(InputStream inputStream, String outputFilePath) throws IOException {
    // Read the file content into a byte array
    byte[] buffer = new byte[inputStream.available()];
    inputStream.read(buffer);

    // Write the bytes in reverse order to a new file
    try (FileOutputStream fos = new FileOutputStream(outputFilePath)) {
        for (int i = buffer.length - 1; i >= 0; i--) {
            fos.write(buffer[i]);
        }
    }
}
