private GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    // Avoids duplicate paths by evaluating each edge tour only once, utilizing visited nodes to track traversals
    HashSet<E> visitedEdges = new HashSet<>();

    List<V> visitedVertices = new ArrayList<>();
    visitedVertices.add(graph.getVertices().iterator().next()); // Start from the first vertex

    GraphPath<V,E> path = new GraphPath<>();
    int edgeCount = path.getEdgeCount();

    // Attempt to iterate through all vertices near the start of path
    while (!visitedVertices.get(visitedVertices.size() - 1).equals(tour.iterator().next()) // Not at the end of the path
    {
        int foundAt = visitedVertices.size() - 1;
        for(int i = 0; i < visitedVertices.size(); i++)
        {
            if(graph.getEdgeAtPosition(i,visitedVertices.get(i)) == tour.iterator().next())
            {
                // Replace previous vertex with the found new vertex
                visitedVertices.set(foundAt,visitedVertices.get(i));
            }
        }
    }

    // If there's a remaining vertex to add
    if((edgeCount == path.getEdgeCount() && graph.getEdgeAtPosition(visitedVertices.size() - 1, visitedVertices.get(visitedVertices.size() - 2)) != null) ||
        visitedVertices.size() > graph.getVertices().size())
    {
        throw new IllegalArgumentException("Path does not form a valid tour");
    }

    return path;
}
