private void reload(List<Set<Integer>> bucketsByLabel,List<Integer> labels,int minLabel) {
    bucketsByLabel.get(0).addAll(bucketsByLabel.get(minLabel));
    bucketsByLabel.remove(minLabel);
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        bucketsByLabel.get(i).remove(minLabel);
    }
    for (int i = 0; i < bucketsByLabel.size(); i++) {
        for (int j = i + 1; j < bucketsByLabel.size(); j++) {
            if (!bucketsByLabel.get(i).isEmpty() && bucketsByLabel.get(i).iterator().next() < bucketsByLabel.get(j).iterator().next()) {
                Collections.swap(bucketsByLabel, i, j);
            }
        }
    }
    for (int i = labels.size() - 1; i >= 0; i--) {
        if (labels.get(i) == minLabel) {
            labels.set(i, 0);
        }
    }
}
