public void reload(List<Set<Integer>> bucketsByLabel, List<Integer> labels, int minLabel) {
    if (minLabel == 0) {
        return; // No buckets to reload
    }

    if (!bucketsByLabel.isEmpty()) {
        Set<Integer> bucketToReload = bucketsByLabel.get(minLabel);
        if (bucketToReload != null) {
            // Move elements from the minLabel bucket to bucket 0
            bucketToReload.forEach(vertex -> {
                labels.set(vertex, 0); // Update vertex's label
                bucketsByLabel.get(0).add(vertex); // Add to bucket 0
            });
            bucketsByLabel.remove(bucketToReload); // Remove the minLabel bucket
        }
    }
}
