import java.util.ArrayList;
import java.util.List;

public class SuffixSumGenerator {
    /**
     * Computes a suffix sum of the given list of integers. Returns a pair containing the computed
     * suffix sum list and the sum of all elements in the list.
     *
     * @param bounds list of integers
     * @return a pair of List<Integer> for suffix sums and a long for the sum of all elements
     */
    private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
        List<Integer> suffixSums = new ArrayList<>();
        long totalSum = 0;

        for (int i = 0; i < bounds size(); i++) {
            // If it's the first element, the suffix sum is its value.
            suffixSums.add(bounds.get(i));
            // Calculate the total sum so far.
            totalSum += bounds.get(i);
        }

        return new Pair<>(suffixSums, totalSum);
    }

    // Inner class to hold the result
    private static class Pair<T1, T2> {
        private T1 first;
        private T2 second;

        public Pair(T1 first, T2 second) {
            this.first = first;
            this.second = second;
        }

        // Getters for the pair
        public T1 getFirst() {
            return first;
        }

        public T2 getSecond() {
            return second;
        }
    }

    // Method to test the correctness of the computeSuffixSum function
    public static void main(String[] args) {
        List<Integer> bounds = new ArrayList<>();
        bounds.add(1);
        bounds.add(2);
        bounds.add(3);
        bounds.add(4);
        bounds.add(5);

        Pair<List<Integer>, Long> result = computeSuffixSum(bounds);
        System.out.println("Suffix Sums: " + result.getFirst());
        System.out.println("Sum of All Elements: " + result.getSecond());
    }
}
