        if (ch < 0 || ch >= 256) {
            throw new IllegalArgumentException("Invalid character code: " + ch);
        }

        if (charCache[ch] == null) {
            synchronized (CharUtils.class) {
                if (charCache[ch] == null) {
                    charCache[ch] = new Character(ch);
                }
            }
        }

        return charCache[ch];
    }
