private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    // Check if the set of vertices is empty or it contains only one vertex, which is trivially a clique
    if (vertices.isEmpty() || vertices.size() == 1) {
        return true;
    }

    // Iterate over each pair of vertices in the set and check if there is an edge between them
    for (V v : vertices) {
        for (V w : vertices) {
            if (v.equals(w)) {
                continue;
            }
            if (!graph.hasEdge(v, w)) {
                return false;
            }
        }
    }

    // If the function reaches this point, it means all pairs of vertices have an edge, so it is a clique
    return true;
}
```

