    int numVertices = inducedVertices.size();
    boolean isClique = true;

    for (V vertex : inducedVertices) {
        List<E> edges = graph.edgesOf(vertex);
        for (E edge : edges) {
            V otherVertex = graph.other(vertex, edge);
            if (!inducedVertices.contains(otherVertex)) {
                isClique = false;
                break;
            }
        }
        if (!isClique) {
            break;
        }
    }

    return isClique;
}
