public static String applyRelativePath(String path, String relativePath) {
    // Use the Paths class from java.nio.file for a more robust solution
    java.nio.file.Path basePath = java.nio.file.Paths.get(path);
    java.nio.file.Path relativePathPath;

    if (relativePath.startsWith("/")) {
        // If the relative path starts with a slash, use it as is
        relativePathPath = java.nio.file.Paths.get(relativePath);
    } else {
        // Otherwise, append the relative path to the base path
        relativePathPath = basePath.resolve(relativePath);
    }

    // Convert the.nio.Path to a String with Unix-style separators
    return relativePathPath.toAbsolutePath().toString().replace(java.nio.file.PathSeparator.value(), "/");
}
```

```java
public static String applyRelativePath(String path, String relativePath) {
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }
    // Split the relative path into segments
    String[] segments = relativePath.split("/");
    // Use StringBuilder to build the full path
    StringBuilder fullPath = new StringBuilder(path);
    for (String segment : segments) {
        // Skip empty segments
        if (!segment.isEmpty()) {
            fullPath.append('/').append(segment);
        }
    }
    return fullPath.toString();
}
