public int readTag() throws IOException {
    if (isEOF()) {
        return 0;
    }
    int tag = 0;
    int shift = 0;
    while ((tag & 0x80) == 0) {  // Continue until we find a tag byte
        byte nextByte = readByte();
        if (nextByte == -1) {
            throw new EOFException("Unexpected end of file while reading tag");
        }
        tag |= nextByte << shift;
        shift += 7;
    }
    return tag;
}
