int readTag() throws IOException {
    // While we have data left to read
    while (data.offset < data.limit) {
        // Read the next byte
        byte b = data.data[data.offset++];

        // If the byte is 0, we have reached EOF
        if (b == 0) {
            return 0;
        }

        // Check if the byte is a tag, by inspecting the 5 high bits
        if ((b & 0xe0) != 0x80) {
            return b;
        }
    }

    throw new EOFException("Unexpected end of stream");
}
