    System.arraycopy(this.bytes, 0, newBytes, 0, this.size());

    // 3. Add the new bytes to the new vector
    newBytes[newSize - 2] = (byte) byteValue1;
    newBytes[newSize - 1] = (byte) byteValue2;

    // 4. Replace the old vector with the new vector
