public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    FileInputStream fis = new FileInputStream(file);
    InputStreamReader isr = new InputStreamReader(fis);
    BufferedReader br = new BufferedReader(isr);

    String line;
    while ((line = br.readLine()) != null) {
        for (ProfileAnalyzeTimeRange timeRange : timeRanges) {
            if (line.matches(".*" + timeRange.getTimeBegin() + "-" + timeRange.getTimeEnd() + ".*")) {
                ThreadSnapshot snapshot = new ThreadSnapshot(line);
                threadSnapshots.add(snapshot);
                break;
            }
        }
    }

    br.close();
    isr.close();
    fis.close();

    return threadSnapshots;
}
